        for script in curr_soup(['script', 'style']):
            script.decompose()
        # Kill Wayback bars
        for div_id in ['wm-ipp-base', 'wm-ipp-print', 'donato']:
            for div in curr_soup.find_all('div', id=div_id):
                div.decompose()

        # Body text of the html
        try:
            text = curr_soup.body.get_text()
        except:
            text = None
        return text
    else:
        return None

